(function(){"use strict";
const services={
viagem:{name:"Viagens",description:"Passagens, hospedagem e deslocamentos corporativos.",fields:[['origin','Origem','text',true],['destination','Destino','text',true],['departureDate','Data de ida','date',true],['returnDate','Data de volta','date',true],['reason','Motivo da viagem','textarea',true],['needsHotel','Precisa de hospedagem?','select',false,['Não','Sim']],['insuranceRequested','Solicitar seguro viagem?','select',false,['Não','Sim']]]},
mobilidade:{name:"Mobilidade",description:"Deslocamentos e mobilidade corporativa.",fields:[['provider','Modalidade','select',true,['Uber for Business','Táxi corporativo','Outro']],['city','Cidade','text',true],['origin','Origem','text',true],['destination','Destino','text',true],['reason','Motivo do deslocamento','textarea',true]]},
entregas:{name:"Entregas",description:"Envio e movimentação de volumes e encomendas.",fields:[['deliveryType','Tipo de entrega','select',true,['Malote','Entrega','Coleta']],['priority','Prioridade','select',true,['Normal','Alta']],['origin','Origem','text',true],['destination','Destino','text',true],['sender','Remetente','text',true],['recipient','Destinatário','text',true],['itemDescription','Descrição do volume','textarea',true]]},
estacionamento:{name:"Estacionamento",description:"Solicitações relacionadas a estacionamento e veículos.",fields:[['requestType','Tipo de solicitação','select',true,['Solicitação de vaga','Acesso temporário','Alteração de veículo']],['location','Local','text',true],['vehiclePlate','Placa do veículo','text',true],['vehicleModel','Modelo do veículo','text',true],['periodStart','Início do período','datetime-local',true],['periodEnd','Fim do período','datetime-local',true],['justification','Justificativa','textarea',true]]},
correios:{name:"Correios",description:"Postagens e serviços de correspondência.",fields:[['mode','Modalidade','select',true,['SEDEX','PAC','Carta registrada']],['recipient','Destinatário','text',true],['cep','CEP','text',true],['address','Endereço','text',true],['content','Conteúdo da postagem','textarea',true]]},
xerox:{name:"Xerox / Impressões",description:"Cópias, impressões e serviços gráficos.",fields:[['format','Formato','select',true,['A4','A3','Banner','Crachá']],['copies','Quantidade','number',true],['color','Tipo de impressão','select',true,['Colorida','Preto e branco']],['finish','Acabamento','select',true,['Sem acabamento','Grampeado','Espiral','Dobra']],['notes','Instruções e local de entrega','textarea',false]]},
achados_perdidos:{name:"Achados e Perdidos",description:"Registre um item perdido ou encontrado.",fields:[['occurrenceType','O que aconteceu?','select',true,['Encontrei um item','Perdi um item']],['category','Categoria do objeto','select',true,['Documentos/Crachás','Eletrônicos','Óculos','Chaves','Vestuário/Acessórios','Outros']],['location','Local aproximado','text',true],['dateTime','Data e hora aproximada','datetime-local',true],['contact','Contato ou ramal','text',true],['details','Descrição e características','textarea',true]]},
liberacao_acesso:{name:"Acessos",description:"Acesso especial ou comunicação de perda de acesso.",journeys:{ACESSO_ESPECIAL:"Acesso Especial",PERDA_ACESSO:"Perda de Acesso"},fields:[['resource','Recurso, local ou sistema','text',true],['period','Período de vigência','text',true],['justification','Justificativa institucional','textarea',true]]},
autorizacao_excepcional:{name:"Autorizações Excepcionais",description:"Solicitações fora do fluxo padrão.",fields:[['category','Categoria da exceção','select',true,['Orçamentária / Custo','Operacional / Horário','Recurso especial','Procedimento de contingência','Outra']],['validity','Vigência','text',true],['reason','Motivo da exceção','text',true],['justification','Justificativa detalhada','textarea',true]]},
investigacao_ocorrencia:{name:"Investigação de Ocorrência",description:"Fluxo ainda pendente de mapeamento.",disabled:true}
};
function collect(form){const values=Object.fromEntries(new FormData(form).entries());return Object.fromEntries(Object.entries(values).filter(([key])=>!['service','title','journey'].includes(key)).map(([key,value])=>[key,value==='Sim'?true:value==='Não'?false:value]));}
const legacyIds={viagem:{origin:'req-origin',destination:'req-destination',departureDate:'req-dep-date',returnDate:'req-ret-date',reason:'req-reason'},mobilidade:{provider:'req-mob-provider',city:'req-mob-city',origin:'req-mob-origin',destination:'req-mob-dest',reason:'req-mob-reason'},entregas:{deliveryType:'req-ent-type',priority:'req-ent-priority',origin:'req-ent-origin',destination:'req-ent-dest',sender:'req-ent-sender',recipient:'req-ent-recipient',itemDescription:'req-ent-desc'},estacionamento:{requestType:'req-est-type',location:'req-est-location',vehiclePlate:'req-est-plate',vehicleModel:'req-est-model',periodStart:'req-est-period-start',periodEnd:'req-est-period-end',justification:'req-est-justification'},correios:{mode:'req-cor-mode',recipient:'req-cor-recipient',cep:'req-cor-cep',address:'req-cor-address',content:'req-cor-content'},xerox:{format:'req-xer-format',copies:'req-xer-copies',color:'req-xer-color',finish:'req-xer-finish',notes:'req-xer-notes'},achados_perdidos:{occurrenceType:'req-ach-occurrence-type',category:'req-ach-category',location:'req-ach-location',dateTime:'req-ach-datetime',contact:'req-ach-contact',details:'req-ach-details'},autorizacao_excepcional:{category:'req-exc-category',validity:'req-exc-validity',reason:'req-exc-reason',justification:'req-exc-justification'},liberacao_acesso:{accessType:'req-acs-type',resource:'req-acs-resource',userTarget:'req-acs-user',period:'req-acs-period',justification:'req-acs-justification'}};
function collectLegacy(type,doc=document){const map=legacyIds[type]||{},details={};Object.entries(map).forEach(([key,id])=>{const element=doc.getElementById(id);if(element&&element.value!=='')details[key]=element.value});if(type==='viagem'){details.needsHotel=doc.getElementById('req-hotel-check')?.value==='sim';details.insuranceRequested=doc.getElementById('req-insurance-check')?.value==='sim'}return details;}
window.CS360RequestForm={services,collect,collectLegacy};
})();
